using SafetyGateSupport.Models;

namespace SafetyGateSupport.Services;

/// <summary>Read-only defaults merged by stable ID; saved site edits take precedence.</summary>
public static class GuidedTroubleshooting
{
    public static List<TroubleshootingFlow> Merge(List<TroubleshootingFlow> saved)
    {
        var ids = saved.Select(f => f.Id).ToHashSet(StringComparer.OrdinalIgnoreCase);
        return saved.Concat(Defaults().Where(f => !ids.Contains(f.Id))).ToList();
    }

    public static IEnumerable<TroubleshootingFlow> Defaults()
    {
        yield return Flow("builtin-light-v1", "Signal column — wrong colors, dark, or replacement", "light signal Siemens 8WD4613 8WD46 USB configuration", "start",
            Node("start", "Confirm the asset, unit, and signal column model", "Use the unit's assigned drawing and approved .signal file. Configurations differ between units. The built-in USB tool supports Siemens 8WD4613-5JH37, variant 21; uploading is limited to firmware v1.0.3. Isolate the equipment for servicing before connecting USB; opening the port can restart the column.\n\nSource: Safety Gate Troubleshooting, signal-column replacement section; tested independent USB client.",
                [Choice("Check stored settings / upload an approved file", "usb"), Choice("No USB detection", "connection"), Choice("Settings match but the light is wrong", "physical")]),
            Node("usb", "Read and compare before replacing settings", "Select the approved file for this unit, then read the column. MATCH means stored configuration matches; it does not prove power, field inputs, LEDs, or sound work. If different, verify the file assignment before uploading. Upload saves the original configuration, writes once, and checks settings after restart. Keep the .before.signal backup. Never guess a configuration from a similar-looking unit.\n\nIf the file is missing, import the supplied library or use an approved backup from the old column. Do not create a replacement configuration from memory.",
                [Choice("Settings match — check physical behavior", "physical"), Choice("File missing or assignment uncertain", "missing")], "SignalColumn"),
            Node("connection", "Check cable, port, and application access", "Use a USB data cable and close Siemens Configurator or other applications using the port. Refresh the device list; check Windows Device Manager for the supported serial device. Bootloader devices are excluded. If another application holds the port, close it before retrying. A successful read saves an exact configuration backup.\n\nDo not repeatedly retry an upload whose outcome is uncertain; read and compare the stored configuration first.", [Choice("Open USB tool", "usb")]),
            Node("physical", "Compare expected output with actual operation", "In the USB tool, select the safely observed input state under Expected output. Compare actual segments and sound with the stored state. The preview does not measure voltages or force outputs. Check every applicable state using the approved site test procedure. If configuration matches but behavior differs, have qualified personnel check the supply, wiring, input signals, and column against this unit's drawing. Do not bypass controls.\n\nA single matching state is insufficient to certify the entire gate.", [], "SignalColumn"),
            Node("missing", "Find the approved configuration", "Open Support library to import the original schematics/config ZIP on this PC. Select the correct asset and unit before assigning a file. Some drawings/configurations cover paired units; use their explicit labels and documentation. If the old column can still be read, preserve its backup before replacement. Escalate unclear assignments rather than guessing.\n\nSource: Safety Gate Troubleshooting, signal-column replacement section.", [], "Library"));
        yield return Flow("builtin-bea-s600-v1", "BEA LZR-S600 — scanner LED diagnosis", "BEA LZR S600 laser scanner orange red blue detection", "identify",
            Node("identify", "Confirm the label reads LZR-S600", "This guidance applies only to the BEA LZR-S600 from ScannerSafe2Cross.pdf (75.5792.09, 2023-04-11). It does not apply to a UAM scanner. Identify the four indicators before continuing.\n\nSource: LZR-S600 User's Guide, pages 2–3 and 10.",
                [Choice("No blue power LED", "power"), Choice("Detection LED stays red", "red"), Choice("Orange flashes with red detection LEDs", "masked"), Choice("Orange on / detection LEDs orange", "fault"), Choice("Different model or unclear indication", "manual")]),
            Node("power", "Check supply and LED settings", "The manual lists missing power, reversed supply polarity, or LEDs disabled by remote control. Have qualified personnel verify the cable, connection, and supply against the unit drawing. Do not infer absence of power from LEDs alone. If only blue is on, the guide identifies the test-input wiring as a possible cause; refer to the approved wiring diagram rather than bridging inputs.\n\nSource: LZR-S600 User's Guide, page 10.", []),
            Node("red", "Check the detection field for an object", "Keep the controlled area safe. Remove ordinary obstructions and check whether the field touches the floor, wall, or door. Do not change the protected field simply to clear a fault. If alignment or field settings need correction, use trained personnel, the full manual, and a functional test before return to service.\n\nSource: LZR-S600 User's Guide, pages 2 and 10.", []),
            Node("masked", "Check for masking or a missing reference", "The guide lists a missing background reference or a masked sensor. Inspect the mounting position and front screens. Clean with compressed air; if necessary use a soft, clean, damp microfibre cloth, without aggressive products. Reference/field changes and a new Learn require the documented setup and validation procedure.\n\nSource: LZR-S600 User's Guide, pages 2 and 10.", []),
            Node("fault", "Check supply, environment, and persistent errors", "The guide lists supply outside its limits, temperature outside its limits, or an internal error. Verify the exact LED pattern and operating limits in the full manual. Arrange qualified checks of supply and temperature. A persistent internal error requires the manufacturer's troubleshooting/replacement procedure; do not treat a reset alone as a repair.\n\nSource: LZR-S600 User's Guide, pages 10–11.", []),
            Node("manual", "Use the manual for the actual scanner model", "Import/open the supplied scanner documentation from Support library. Confirm model and wiring before applying model-specific instructions. UAM configuration files and BEA scanner settings are not interchangeable.", [], "Library"));
        yield return Flow("builtin-uam-v1", "UAM scanner — configuration or replacement", "UAM Hokuyo scanner sensor hux detection zone replacement", "identify",
            Node("identify", "Confirm a UAM scanner is installed", "Read the device label and the unit drawing. The supplied site guide directs UAM devices to UAM Project Designer over Micro-USB. Preserve the existing configuration where readable. The supplied Omni Sensors archive contains .hux configurations, not the installer. Match asset AND unit; filenames contain spelling inconsistencies, so assignments require review.\n\nSource: Safety Gate Troubleshooting, sensor replacement / detection-zone section.",
                [Choice("Find the assigned scanner configuration", "config"), Choice("Replace or change detection zones", "replace")]),
            Node("config", "Open the unit's scanner resources", "Use the scanner configuration resource for this unit or import the Omni Sensors ZIP through Support library. Launch the installed UAM Project Designer explicitly. Read and retain the current scanner configuration before changing it. Do not apply a file for a different unit solely because the asset matches.", [], "Library"),
            Node("replace", "Follow the exact model's transfer and validation procedure", "The site guide refers to pages 119–121 of its UAM manual for replacement transfer; page numbers may differ between revisions. Locate that procedure in the actual installed-model manual. Replacing a scanner or modifying detection zones requires the documented checks of the complete protective function before the system is returned to service. The application does not program or validate scanner safety fields.", [], "Library"));
        yield return Flow("builtin-actuator-v1", "Actuator — replacement and programming", "LINAK BusLink actuator gate arm programming replacement", "start",
            Node("start", "Identify the gate or arm actuator", "Match the fitted actuator, stroke, and approved program to this unit. The site guide says stockroom actuators should arrive programmed; check before reprogramming. The supplied parts lists and site notes use different actuator part/stroke descriptions, so confirm the installed part and current stockroom record. Do not substitute based on this guide alone.\n\nSources: Safety Gate Troubleshooting; I.C. Actuator Programing Guide; supplied spare-parts lists.",
                [Choice("Need to program a replacement", "program"), Choice("Program appears correct but motion is wrong", "mechanical")]),
            Node("program", "Use BusLink with the correct cable and program", "Read I.C. Actuator Programing Guide before connecting. It describes powering off, connecting the dedicated actuator programming cable, opening BusLink2, and the documented power-on sequence. In BusLink use Configure → Import/Export, select the approved Gate or Arm program, then Apply. Disconnect through BusLink before reconnecting the actuator to the system.\n\nImport the complete BusLink ZIP so DLLs and resources remain alongside BusLink2.exe. The app opens the vendor tool on request; it does not write actuator settings itself.\n\nSource: I.C. Actuator Programing Guide, pages 2–6.", [], "Library"),
            Node("mechanical", "Verify installation and intended operation", "Use qualified maintenance personnel to inspect installation, connections, and the approved actuator program. Keep the movement area controlled and follow isolation procedures for mechanical work. After reconnection, perform the documented functional tests for both gate and arm before return to service.\n\nSource: I.C. Actuator Programing Guide, final page.", []));
    }

    private static TroubleshootingChoice Choice(string text, string target) => new() { Text = text, NextNodeId = target };
    private static TroubleshootingNode Node(string id, string prompt, string body, List<TroubleshootingChoice> choices, string action = "") => new() { Id = id, Prompt = prompt, Body = body, Choices = choices, IsTerminal = choices.Count == 0, Action = action };
    private static TroubleshootingFlow Flow(string id, string title, string keywords, string start, params TroubleshootingNode[] nodes) => new() { Id = id, Title = title, Keywords = keywords, ManufacturerFilter = "Safe2Cross", StartNodeId = start, Nodes = nodes.ToList() };
}
